package order_service.controller;import order_service.dto.ItemDto;import order_service.service.ItemService;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import java.util.List;@RestController@RequestMapping("/items")@RequiredArgsConstructorpublic class ItemController {    public final ItemService itemService;    @GetMapping()    public ResponseEntity<List<ItemDto>> getAllItems() {        return ResponseEntity.ok(itemService.getAllItems());    }}